// Function to sort the array according to frequency
vector<int> sortByFreq(vector<int> &arr)
{
    int n = arr.size();

    // Map stores elements in a self-balancing BST
    map<int, int> mp;

    // Store the frequency of each element
    for (int i = 0; i < n; i++)
        mp[arr[i]]++;

    // Store frequency and element
    vector<vector<int>> freq;

    for (auto it : mp)
        freq.push_back({it.second, it.first});

    // Sort by frequency in descending order
    // If frequency is same, sort by value in ascending order
    sort(freq.begin(), freq.end(), [](vector<int> &a, vector<int> &b) {
        if (a[0] == b[0])
            return a[1] < b[1];
        return a[0] > b[0];
    });

    // Store the answer
    vector<int> res;

    for (auto &it : freq)
    {
        for (int j = 0; j < it[0]; j++)
            res.push_back(it[1]);
    }

    return res;
}

