    def sortByFreq(arr):

    # Sort the array so equal elements are together.
    arr.sort()

    # AVL tree arrays
    key = []
    freq = []
    left = []
    right = []
    height = []

    def newNode(x, f):
        i = len(key)
        key.append(x)
        freq.append(f)
        left.append(-1)
        right.append(-1)
        height.append(1)
        return i

    def getHeight(x):
        return 0 if x == -1 else height[x]

    def updateHeight(x):
        lh = getHeight(left[x])
        rh = getHeight(right[x])
        height[x] = max(lh, rh) + 1

    def rotateRight(x):
        y = left[x]
        t = right[y]

        right[y] = x
        left[x] = t

        updateHeight(x)
        updateHeight(y)

        return y

    def rotateLeft(x):
        y = right[x]
        t = left[y]

        left[y] = x
        right[x] = t

        updateHeight(x)
        updateHeight(y)

        return y

    def insert(root, x, f):

        if root == -1:
            return newNode(x, f)

        if x < key[root]:
            left[root] = insert(left[root], x, f)

        elif x > key[root]:
            right[root] = insert(right[root], x, f)

        else:
            freq[root] = f
            return root

        updateHeight(root)

        balance = getHeight(left[root]) - getHeight(right[root])

        # Left-left
        if balance > 1 and x < key[left[root]]:
            return rotateRight(root)

        # Left-right
        if balance > 1 and x > key[left[root]]:
            left[root] = rotateLeft(left[root])
            return rotateRight(root)

        # Right-right
        if balance < -1 and x > key[right[root]]:
            return rotateLeft(root)

        # Right-left
        if balance < -1 and x < key[right[root]]:
            right[root] = rotateRight(right[root])
            return rotateLeft(root)

        return root

    # Build frequency list from sorted array.
    values = []
    i = 0
    n = len(arr)

    while i < n:
        j = i + 1

        while j < n and arr[j] == arr[i]:
            j += 1

        values.append((arr[i], j - i))
        i = j

    # Build the self-balancing BST using distinct elements.
    root = -1

    for x, f in values:
        root = insert(root, x, f)

    # Store nodes using inorder traversal.
    nodes = []
    stack = []
    cur = root

    while stack or cur != -1:

        while cur != -1:
            stack.append(cur)
            cur = left[cur]

        cur = stack.pop()

        nodes.append((freq[cur], key[cur]))

        cur = right[cur]

    # Sort by frequency descending and value ascending.
    nodes.sort(key=lambda x: (-x[0], x[1]))

    # Build the result.
    res = []

    for f, x in nodes:
        res.extend([x] * f)

    return res


