class GFG
{
    // Function to sort the array according to frequency
    public static List<int> sortByFreq(int[] arr)
    {
        int n = arr.Length;

        // Map stores elements and their frequencies
        Dictionary<int, int> mp = new Dictionary<int, int>();

        // Store the frequency of each element
        for (int i = 0; i < n; i++)
        {
            if (mp.ContainsKey(arr[i]))
                mp[arr[i]]++;
            else
                mp[arr[i]] = 1;
        }

        // Store frequency and element
        List<Tuple<int, int>> freq = new List<Tuple<int, int>>();

        foreach (var kvp in mp)
            freq.Add(new Tuple<int, int>(kvp.Value, kvp.Key));

        // Sort by frequency in descending order
        // If frequency is same, sort by value in ascending order
        freq.Sort((a, b) =>
            a.Item1 == b.Item1
                ? a.Item2.CompareTo(b.Item2)
                : b.Item1.CompareTo(a.Item1));

        // Store the answer
        List<int> res = new List<int>();

        foreach (var it in freq)
        {
            for (int j = 0; j < it.Item1; j++)
                res.Add(it.Item2);
        }

        return res;
    }

