    using System;
using System.Collections.Generic;

class GFG {
    // Max heap for storing frequency and element
    class MaxHeap {
        List<int[]> heap = new List<int[]>();

        // Compare two elements
        bool Greater(int[] a, int[] b)
        {
            if (a[0] != b[0])
                return a[0] > b[0];

            return a[1] > b[1];
        }

        // Add an element to the heap
        public void Push(int[] item)
        {
            heap.Add(item);

            int i = heap.Count - 1;

            while (i > 0) {
                int parent = (i - 1) / 2;

                if (!Greater(heap[i], heap[parent]))
                    break;

                int[] temp = heap[i];
                heap[i] = heap[parent];
                heap[parent] = temp;

                i = parent;
            }
        }

        // Remove and return the maximum element
        public int[] Pop()
        {
            int[] res = heap[0];

            heap[0] = heap[heap.Count - 1];
            heap.RemoveAt(heap.Count - 1);

            int i = 0;

            while (true) {
                int left = 2 * i + 1;
                int right = 2 * i + 2;
                int largest = i;

                if (left < heap.Count
                    && Greater(heap[left], heap[largest]))
                    largest = left;

                if (right < heap.Count
                    && Greater(heap[right], heap[largest]))
                    largest = right;

                if (largest == i)
                    break;

                int[] temp = heap[i];
                heap[i] = heap[largest];
                heap[largest] = temp;

                i = largest;
            }

            return res;
        }

        public bool IsEmpty() { return heap.Count == 0; }
    }

    // Function to sort the array according to frequency of
    // elements
    public List<int> sortByFreq(int[] arr)
    {
        int n = arr.Length;

        // Hash map to store the frequency of each element
        Dictionary<int, int> mp
            = new Dictionary<int, int>();

        // Store the frequency of each element
        for (int i = 0; i < n; i++) {
            if (!mp.ContainsKey(arr[i]))
                mp[arr[i]] = 0;

            mp[arr[i]]++;
        }

        // Priority queue implemented using max heap
        MaxHeap pq = new MaxHeap();

        // Store the frequency and the element
        foreach(var item in mp)
        {
            // Store the negative of element
            // to sort elements with same
            // frequency in ascending order
            pq.Push(new int[] { item.Value, -item.Key });
        }

        // To store the answer
        List<int> res = new List<int>();

        // Push the elements in the answer array
        while (!pq.IsEmpty()) {
            int[] top = pq.Pop();

            int freq = top[0];
            int ele = -top[1];

            for (int i = 0; i < freq; i++)
                res.Add(ele);
        }

        return res;
    }

    public static void Main()
    {
        int[] arr = { 5, 5, 4, 6, 4 };

        List<int> ans = new GFG().sortByFreq(arr);

        for (int i = 0; i < ans.Count; i++)
            Console.Write(ans[i] + " ");
    }
}


